content:
:root {
  --primary-color: #ff6b6b;
  --primary-hover: #fa5252;
  --secondary-color: #4dabf7;
  --pause-color: #fcc419;
  --pause-hover: #f59f00;
  --reset-color: #adb5bd;
  --reset-hover: #868e96;
  --bg-gradient: linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%);
  --card-bg: #ffffff;
  --text-color: #343a40;
  --shadow: 0 10px 25px rgba(0, 0, 0, 0.05);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  background: var(--bg-gradient);
  color: var(--text-color);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
}

.app-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 20px;
  width: 100%;
  max-width: 480px;
}

.timer-card {
  background: var(--card-bg);
  padding: 40px 30px;
  border-radius: 24px;
  box-shadow: var(--shadow);
  text-align: center;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 30px;
}

.timer-display {
  font-size: 5rem;
  font-weight: 700;
  letter-spacing: -2px;
  color: var(--text-color);
  font-variant-numeric: tabular-nums;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  width: 100%;
}

.btn {
  padding: 12px 24px;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: 12px;
  cursor: pointer;
  transition: all 0.2s ease;
  color: #ffffff;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1);
}

.btn:active {
  transform: translateY(2px);
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
}

.btn-start {
  background-color: var(--primary-color);
}

.btn-start:hover {
  background-color: var(--primary-hover);
}

.btn-pause {
  background-color: var(--pause-color);
}

.btn-pause:hover {
  background-color: var(--pause-hover);
}

.btn-reset {
  background-color: var(--reset-color);
}

.btn-reset:hover {
  background-color: var(--reset-hover);
}

.progress-bar {
  width: 100%;
  height: 8px;
  background-color: #e9ecef;
  border-radius: 4px;
  overflow: hidden;
  position: relative;
}

.progress-fill {
  height: 100%;
  background-color: var(--primary-color);
  transition: width 0.5s linear;
  border-radius: 4px;
}

import { useState, useEffect, useRef } from 'react';
import './index.css';

const TOTAL_TIME = 25 * 60; // 25分 = 1500秒

export default function App() {
  const [timeLeft, setTimeLeft] = useState<number>(TOTAL_TIME);
  const [isRunning, setIsRunning] = useState<boolean>(false);
  const timerRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => {
    if (isRunning) {
      timerRef.current = setInterval(() => {
        setTimeLeft((prev) => {
          if (prev <= 1) {
            setIsRunning(false);
            if (timerRef.current) {
              clearInterval(timerRef.current);
            }
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    } else {
      if (timerRef.current) {
        clearInterval(timerRef.current);
      }
    }

    return () => {
      if (timerRef.current) {
        clearInterval(timerRef.current);
      }
    };
  }, [isRunning]);

  const handleStart = () => {
    if (timeLeft > 0) {
      setIsRunning(true);
    }
  };

  const handlePause = () => {
    setIsRunning(false);
  };

  const handleReset = () => {
    setIsRunning(false);
    setTimeLeft(TOTAL_TIME);
  };

  const minutes = Math.floor(timeLeft / 60);
  const seconds = timeLeft % 60;
  const formattedTime = `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;

  const progressPercentage = ((TOTAL_TIME - timeLeft) / TOTAL_TIME) * 100;

  return (
    <div className="app-container">
      <div className="timer-card">
        <h1 style={{ fontSize: '1.5rem', fontWeight: 600, color: 'var(--text-color)' }}>
          ポモドーロタイマー
        </h1>
        <div className="timer-display">{formattedTime}</div>
        <div className="progress-bar">
          <div className="progress-fill" style={{ width: `${progressPercentage}%` }}></div>
        </div>
        <div className="controls">
          {!isRunning ? (
            <button className="btn btn-start" onClick={handleStart}>
              開始
            </button>
          ) : (
            <button className="btn btn-pause" onClick={handlePause}>
              一時停止
            </button>
          )}
          <button className="btn btn-reset" onClick={handleReset}>
            リセット
          </button>
        </div>
      </div>
    </div>
  );
}
